pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 seed) public {
        // Restrict amount to a reasonable range to avoid overflow in setup
        amount = bound(amount, 1, 1000 ether);
        // Pre-fund C with some ether, simulating previous deposits
        uint256 initialBalance = amount + (seed % 100 ether);
        vm.deal(address(this), initialBalance + amount);
        (bool ok,) = address(c).call{value: initialBalance}("");
        require(ok, "funding failed");

        // Record owner's balance before
        uint256 ownerBalanceBefore = c.owner().balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Call go() with the fuzzed amount
        vm.deal(address(this), amount);
        c.go{value: amount}();

        // After go(), the owner should have received exactly contractBalanceBefore (the entire contract balance before the call)
        // because go() sends the whole balance of C to the owner.
        // The bug sends msg.value to the zero address, so less ether is available to transfer to the owner.
        uint256 ownerBalanceAfter = c.owner().balance;
        assertTrue(ownerBalanceAfter == ownerBalanceBefore + contractBalanceBefore);
    }
}

