pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 firstAmount, uint256 secondAmount) public {
        // Restrict to plausible positive values to trigger the payment path.
        // Keep domain wide enough for the fuzzer to find violations.
        firstAmount = bound(firstAmount, 1, 1000 ether);
        secondAmount = bound(secondAmount, 1, 1000 ether);

        // First call by the owner with firstAmount.
        address owner = c.owner();
        vm.deal(owner, firstAmount);
        vm.prank(owner);
        c.go{value: firstAmount}();

        uint256 ownerBalanceAfterFirst = owner.balance;

        // Second call by a different actor with secondAmount.
        address caller2 = address(0xBEEF);
        vm.deal(caller2, secondAmount);
        vm.prank(caller2);
        c.go{value: secondAmount}();

        uint256 ownerBalanceAfterSecond = owner.balance;

        // The owner's balance after the second call must exceed the balance after the first call.
        // The correct contract retains the first value in its balance, so the second call
        // sends (firstAmount + secondAmount) to the owner, increasing the owner's balance.
        // The buggy contract sends only its current balance (which is only secondAmount after
        // the first call drained it), so the owner ends up with the same or lower balance,
        // violating this invariant.
        assertTrue(ownerBalanceAfterSecond > ownerBalanceAfterFirst);
    }
}

