pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        address reverter = address(new Reverter());
        // Replace the hardcoded target with a reverter, so the external call always fails.
        // The reference does not send Ether to the owner when the call reverts, while the buggy version does.
        vm.etch(address(0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C), address(reverter).code);

        address owner = c.owner();
        uint256 ownerBefore = owner.balance;

        // Fund the test contract so it can send Ether with the call
        vm.deal(address(this), amount);
        // We need to call go on behalf of some EOA, e.g., address(this) or another address; prank as the caller
        vm.prank(address(this));
        bool ok = true;
        try c.go{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }
        // The call should revert because the target is a reverter
        assertTrue(!ok);

        uint256 ownerAfter = owner.balance;
        // Reference: owner balance does not change because entire balance transfer is skipped on revert.
        // Buggy: owner receives the contract's prior balance (which is 0) plus msg.value before the revert, so owner gains amount.
        assertTrue(ownerAfter == ownerBefore);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
}

