        preFunds = bound(preFunds, 0, 1000 ether);

        // Fund the contract with some Ether to create a pre-existing balance.
        // The fuzzer chooses the amount of pre-existing funds.
        if (preFunds > 0) {
            vm.deal(address(c), preFunds);
        }

        // The fuzzer chooses the msg.value sent to go().
        address actor = makeAddr("actor");
        vm.deal(actor, msgValue);
        vm.prank(actor);
        c.go{value: msgValue}();

        // The reference contract (C) always sends its entire balance to the owner,
        // leaving the contract balance zero after any successful call.
        // The buggy version sends balance to owner BEFORE the external call,
        // so any Ether received from the external call (e.g., if the target sends back)
        // could leave the contract with a non-zero balance.
        assertEq(address(c).balance, 0, "Contract balance must be zero after go()");
    }
}

